import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].unitPrice, 9500);
  assert.equal(result.value.lines[0].vatRate, 21);

  assert.equal(result.value.lines[1].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].unitPrice, 8500);
  assert.equal(result.value.lines[1].vatRate, 21);
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for missing date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for wrong format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '07-10-2026',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026/10/07',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-7',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports NO_LINES for empty lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-positive quantities', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: '5' }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for missing product', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice uses the first error encountered', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: 'invalid',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice enriches lines from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].name, 'Logo package');
  assert.equal(result.value.lines[0].unitPrice, 120000);
  assert.equal(result.value.lines[0].vatRate, 21);

  assert.equal(result.value.lines[1].name, 'Printed flyer A4 (each)');
  assert.equal(result.value.lines[1].unitPrice, 37);
  assert.equal(result.value.lines[1].vatRate, 9);

  assert.equal(result.value.lines[2].name, 'Brand workshop (day, VAT exempt)');
  assert.equal(result.value.lines[2].unitPrice, 60000);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };
  const originalLines = input.lines;

  createInvoice(input);

  assert.equal(input.lines, originalLines);
  assert.equal(Object.keys(input.lines[0]).length, 2);
  assert.equal(input.lines[0].sku, 'DEV-HOUR');
  assert.equal(input.lines[0].qty, 5);
});

test('createInvoice normalizes customerId before storing', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customerId with whitespace', () => {
  const result = createInvoice({
    customerId: '  c-003  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice accepts mixed case customer IDs', () => {
  const result = createInvoice({
    customerId: 'c-008',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-008');
});

test('createInvoice still rejects unknown normalized IDs', () => {
  const result = createInvoice({
    customerId: 'c-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice defaults to NET30 payment terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06'); // Oct 7 + 30 days
});

test('createInvoice calculates due date for NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2026-10-21'); // Oct 7 + 14 days
});

test('createInvoice calculates due date for NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06'); // Oct 7 + 30 days
});

test('createInvoice calculates due date for EOM (end of month) terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2026-10-31'); // End of October
});

test('createInvoice EOM works on last day of month', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-31',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2026-10-31'); // Already last day
});

test('createInvoice EOM works across month boundaries', () => {
  // February last day varies
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2026-02-28'); // Feb 28, 2026 (not a leap year)
});

test('createInvoice rejects unknown payment terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'INVALID',
  });

  assert.deepEqual(result, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice handles NET30 crossing year boundary', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2027-01-14'); // Crosses to next year
});

test('createInvoice handles EOM crossing year boundary', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2026-12-31'); // End of December
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 9500 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 47500);
});

test('lineTotal works with different amounts', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }).value, 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }).value, 3700);
  assert.equal(lineTotal({ qty: 2, unitPrice: 60000 }).value, 120000);
});

test('lineTotal reports AMOUNT_INVALID for missing fields', () => {
  assert.deepEqual(lineTotal({ qty: 5 }), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(lineTotal({ unitPrice: 9500 }), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(lineTotal({}), { ok: false, error: 'AMOUNT_INVALID' });
});

test('lineTotal reports AMOUNT_INVALID for non-number values', () => {
  assert.deepEqual(lineTotal({ qty: '5', unitPrice: 9500 }), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(lineTotal({ qty: 5, unitPrice: '9500' }), { ok: false, error: 'AMOUNT_INVALID' });
